def safe_filename(name: str, maxlen: int = 120) -> str:
	"""A name usable as a file or folder name on Windows, macOS and Linux."""
	bad = '<>:"/\\|?*'
	out = "".join("_" if (c in bad or ord(c) < 32) else c for c in name).strip(" .")
